(12183, 'iss_related_places', 'a:12:{i:0;a:8:{s:8:"place_id";i:17960;s:4:"role";s:4:"stop";s:6:"weight";i:10;s:5:"label";s:27:"Industriesalon Schöneweide";s:11:"route_title";s:27:"Industriesalon Schöneweide";s:12:"route_teaser";s:172:"Auftaktstation der Elektropolis-Führung mit Bezügen zu Straßen- und Industriegeschichte, DDR-Poliklinik, Zwangsarbeit, Reinbeckhallen und neuen Kulturorten an der Spree.";s:17:"station_object_id";i:18857;s:16:"station_story_id";i:13257;}i:1;a:8:{s:8:"place_id";i:17966;s:4:"role";s:4:"stop";s:6:"weight";i:20;s:5:"label";s:19:"Reinbeckstraße 4-8";s:11:"route_title";s:24:"Ehemalige DDR-Poliklinik";s:12:"route_teaser";s:124:"Station zur ehemaligen DDR-Poliklinik in der Reinbeckstraße 4-8 als Teil der sozialen Infrastruktur des Industriequartiers.";s:17:"station_object_id";i:15951;s:16:"station_story_id";i:17980;}i:2;a:8:{s:8:"place_id";i:17969;s:4:"role";s:4:"stop";s:6:"weight";i:30;s:5:"label";s:10:"Kaisersteg";s:11:"route_title";s:40:"Unter der Kranbahn / Platz am Kaisersteg";s:12:"route_teaser";s:177:"An Kranbahn und Kaisersteg wird sichtbar, wie schwere Bauteile, Industrieporzellan und andere Güter für die Werke an der Wilhelminenhofstraße angeliefert und verteilt wurden.";s:17:"station_object_id";i:0;s:16:"station_story_id";i:5695;}i:3;a:8:{s:8:"place_id";i:17970;s:4:"role";s:4:"stop";s:6:"weight";i:40;s:5:"label";s:24:"Wilhelminenhofstraße 78";s:11:"route_title";s:21:"Umspannwerk Oberspree";s:12:"route_teaser";s:177:"Zwischen Umspannwerk, Schalthaus und Werksgeländen zeigt sich, wie eng Produktion von Hochspannungstechnik und städtische Energieverteilung in Oberschöneweide verzahnt waren.";s:17:"station_object_id";i:0;s:16:"station_story_id";i:2953;}i:4;a:8:{s:8:"place_id";i:17971;s:4:"role";s:4:"stop";s:6:"weight";i:50;s:5:"label";s:24:"Wilhelminenhofstraße 77";s:11:"route_title";s:19:"Kraftwerk Oberspree";s:12:"route_teaser";s:136:"Hier wird die Energieinfrastruktur sichtbar, ohne die Kabelwerk, TRO und die wachsende Elektropolis n